88	+{
89	+    uint64_t golden_v = 0, actual_v = 0;
90	+    memcpy(&golden_v, golden, (size_t)width);
91	+    memcpy(&actual_v, actual, (size_t)width);
92	+    uint64_t xor_v = golden_v ^ actual_v;
93	+    char golden_hex[2 * 8 + 1], actual_hex[2 * 8 + 1], xor_hex[2 * 8 + 1];
94	+    for (int i = 0; i < width; ++i) {
