103	+              "golden=%s actual=%s xor=%s",
104	+              (unsigned long long)elem_index, (unsigned long long)byte_offset, width,
105	+              (unsigned long long)golden_v, (unsigned long long)actual_v,
106	+              (unsigned long long)xor_v, width - 1, golden_hex, actual_hex, xor_hex);
107	+    report_fail_msg("MovBE-SLF-sweep: round-trip failed at element %llu "
108	+                    "(byte offset %llu, width %d)",
109	+                    (unsigned long long)elem_index, (unsigned long long)byte_offset, width);
