112	+/* init 自检 (fail-closed): 每种宽度 N 个随机值过 svtbl 机制 (栈缓冲),
113	+ * 逐位对照 __builtin_bswap16/32/64 — 任一不符即 fail init (绝不静默 SUCCESS) */
114	+static void slf_sweep_selfcheck(int width)
115	+{
116	+    const uint64_t vbytes = (uint64_t)svcntb();
117	+    uint8_t vidx_bytes[SVE_MAX_VECTOR_BYTES];
118	+    slf_sweep_build_index_table(vidx_bytes, vbytes, width);
119	+    svbool_t pg_full = svwhilelt_b8((uint64_t)0, vbytes);
120	+    svuint8_t vidx = svld1_u8(pg_full, vidx_bytes);
121	+
122	+    uint8_t src[SVE_MAX_VECTOR_BYTES];
123	+    uint8_t dst[SVE_MAX_VECTOR_BYTES];
124	+    uint64_t checked = 0;
125	+    while (checked < SLF_SWEEP_SELFCHECK_VECS) {
126	+        uint64_t count = vbytes / (uint64_t)width;
127	+        if (count > (uint64_t)SLF_SWEEP_SELFCHECK_VECS - checked)
128	+            count = (uint64_t)SLF_SWEEP_SELFCHECK_VECS - checked;
129	+        uint64_t nbytes = count * (uint64_t)width;
130	+
131	+        for (uint64_t e = 0; e < count; ++e) {
132	+            if (width == 2) {
133	+                uint16_t v = (uint16_t)random32();
134	+                memcpy(src + e * 2, &v, 2);
135	+            } else if (width == 4) {
136	+                uint32_t v = random32();
137	+                memcpy(src + e * 4, &v, 4);
138	+            } else {
139	+                uint64_t v = random64();
140	+                memcpy(src + e * 8, &v, 8);
141	+            }
142	+        }
143	+
144	+        svbool_t pg = svwhilelt_b8((uint64_t)0, nbytes);
145	+        svuint8_t permuted = svtbl_u8(svld1_u8(pg, src), vidx);
146	+        svst1_u8(pg, dst, permuted);
147	+
148	+        for (uint64_t e = 0; e < count; ++e) {
149	+            uint8_t expected[8];
150	+            if (width == 2) {
151	+                uint16_t v, x;
152	+                memcpy(&v, src + e * 2, 2);
153	+                x = __builtin_bswap16(v);
154	+                memcpy(expected, &x, 2);
155	+            } else if (width == 4) {
156	+                uint32_t v, x;
157	+                memcpy(&v, src + e * 4, 4);
158	+                x = __builtin_bswap32(v);
159	+                memcpy(expected, &x, 4);
160	+            } else {
161	+                uint64_t v, x;
162	+                memcpy(&v, src + e * 8, 8);
163	+                x = __builtin_bswap64(v);
164	+                memcpy(expected, &x, 8);
165	+            }
