210	+static int movbe_slf_sweep_sve_run(struct test *test, int cpu)
211	+{
212	+    (void)cpu;
213	+    auto *data = (movbe_slf_sweep_sve_data *)test->data;
214	+
215	+    const uint64_t total = SLF_SWEEP_BUFFER_BYTES;
216	+    const uint64_t vbytes = (uint64_t)svcntb();
217	+    /* SVE 架构保证 VL 是 128bit 的倍数 → vbytes 是 16 的倍数 → 对 W∈{2,4,8}
218	+     * 每批 (含 svwhilelt 尾批) 恒元素对齐; 索引表 256 字节定容封死 VL≥1024 溢出 */
219	+
220	+    /* 每线程私有副本 (SLF 探针, 消除多写者竞争; 同 probe-c。fork 模型下
221	+     * 随子进程退出回收, cleanup 只释放 test->data 所辖分配 — 同家族约定) */
222	+    static thread_local uint8_t *priv = nullptr;
223	+    if (!priv)
224	+        priv = (uint8_t *)aligned_alloc(64, SLF_SWEEP_BUFFER_BYTES);
225	+
226	+    /* 三种宽度的索引表, 每 run-call 建一次 (svuint8_t 是 sizeless 类型,
227	+     * 不能作数组元素, 故向量本体在宽度循环内从表中加载) */
228	+    static const int widths[3] = {2, 4, 8};
229	+    uint8_t vidx_bytes[3][SVE_MAX_VECTOR_BYTES];
230	+    for (int w = 0; w < 3; ++w)
231	+        slf_sweep_build_index_table(vidx_bytes[w], vbytes, widths[w]);
232	+    svbool_t pg_idx = svwhilelt_b8((uint64_t)0, vbytes);
233	+
234	+    TEST_LOOP(test, 1 << 13) {
235	+        /* 改进 A: 每遍在 16/32/64-bit 三种元素宽度间轮换扫描 */
236	+        for (int w = 0; w < 3; ++w) {
237	+            const int width = widths[w];
238	+            svuint8_t vidx = svld1_u8(pg_idx, vidx_bytes[w]);
239	+
240	+            /* 每遍宽度扫描前重置私有副本 (store-back 污染; 同 probe-c) */
241	+            memcpy(priv, data->golden, total);
242	+
243	+            for (uint64_t base = 0; base < total; base += vbytes) {
244	+                uint64_t n = (total - base < vbytes) ? total - base : vbytes;
245	+                svbool_t pg = svwhilelt_b8((uint64_t)0, n);
246	+
247	+                /* 载入本批字节 (向量) → 元素内字节重排 */
248	+                svuint8_t vswapped = svtbl_u8(svld1_u8(pg, priv + base), vidx);
249	+
250	+                /* ★ SLF 核心: 交换结果存回同一地址 (svst1 直打堆无栈中转) */
251	+                svst1_u8(pg, priv + base, vswapped);
252	+                __asm__ volatile("" ::: "memory");
253	+                /* ★ 立即重读同一地址 (真实 store→load 转发)。asm memory barrier
254	+                 * 阻断编译器消除真实 reload (无屏障时破坏 SLF 语义, 同 probe-c) */
255	+                svuint8_t reloaded = svld1_u8(pg, (const uint8_t *)priv + base);
256	+
257	+                /* 再交换一次还原 (同一索引表, svtbl 对合) → 栈 scratch */
258	+                svuint8_t vrestored = svtbl_u8(reloaded, vidx);
259	+                uint8_t out_bytes[SVE_MAX_VECTOR_BYTES];
260	+                svst1_u8(pg, out_bytes, vrestored);
261	+
262	+                /* 校验: 还原字节 == golden 字节 (按字节, 与宽度解耦);
263	+                 * ONLY on failure: dump index/width/golden/actual/xor + 字节分解 */
264	+                for (uint64_t i = 0; i < n; ++i) {
265	+                    if (out_bytes[i] != data->golden[base + i]) {
266	+                        uint64_t elem_off = (i / (uint64_t)width) * (uint64_t)width;
267	+                        slf_sweep_report_fail((base + elem_off) / (uint64_t)width,
268	+                                              base + elem_off, width,
269	+                                              data->golden + base + elem_off,
270	+                                              out_bytes + elem_off);
271	+                    }
272	+                }
273	+            }
274	+        }
275	+    }
276	+
277	+    return EXIT_SUCCESS;
278	+}
279	+#else
280	+static int movbe_slf_sweep_sve_run(struct test *test, int cpu)
281	+{
282	+    (void)test; (void)cpu;
283	+    log_skip(CpuNotSupportedSkipCategory,
284	+             "to be implemented (placeholder): ARM SVE required for movbe_slf_sweep_sve");
285	+    return EXIT_SKIP;
286	+}
287	+#endif
288	+
289	+static int movbe_slf_sweep_sve_cleanup(struct test *test)
290	+{
291	+    auto *data = (movbe_slf_sweep_sve_data *)test->data;
292	+    if (data) {
293	+        /* 改进 C: cleanup 释放 test->data 所辖全部分配 (无死分配) */
294	+        free(data->golden);
295	+        free(data);
296	+    }
297	+    return EXIT_SUCCESS;
298	+}
299	+
