static int movbe_dump_probe_c_sve_cleanup(struct test *test)
{
    auto *data = (movbe_dump_probe_c_sve_data *)test->data;
    if (data) {
        free(data->input);
        free(data->swapped);
        free(data);
    }
    return EXIT_SUCCESS;
}

